"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[44074],{3331:(e,n,i)=>{i.d(n,{R:()=>o,x:()=>s});var r=i(36672);const t={},a=r.createContext(t);function o(e){const n=r.useContext(a);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),r.createElement(a.Provider,{value:n},e.children)}},71062:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>s,default:()=>h,frontMatter:()=>o,metadata:()=>r,toc:()=>d});const r=JSON.parse('{"id":"2023/04/02","title":"02","description":"Amazon Echo apparaten slaan WiFi-wachtwoorden op in platte tekst, waardoor ze kwetsbaar zijn voor fysieke aanval.","source":"@site/i18n/nl/docusaurus-plugin-content-docs/current/2023/04/02.md","sourceDirName":"2023/04","slug":"/2023/04/02","permalink":"/nl/2023/04/02","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nl/docusaurus-plugin-content-docs//current/2023/04/02.md","tags":[],"version":"current","frontMatter":{"localized_date":"2 april 2023","top_news":"Amazon Echo apparaten slaan WiFi-wachtwoorden op in platte tekst, waardoor ze kwetsbaar zijn voor fysieke aanval."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-03","permalink":"/nl/2023/04/03"},"next":{"title":"01","permalink":"/nl/2023/04/01"}}');var t=i(23420),a=i(3331);const o={localized_date:"2 april 2023",top_news:"Amazon Echo apparaten slaan WiFi-wachtwoorden op in platte tekst, waardoor ze kwetsbaar zijn voor fysieke aanval."},s=void 0,l={},d=[{value:"Amazon Echo apparaten slaan WiFi-wachtwoorden op in platte tekst, waardoor ze kwetsbaar zijn voor fysieke aanval.",id:"amazon-echo-apparaten-slaan-wifi-wachtwoorden-op-in-platte-tekst-waardoor-ze-kwetsbaar-zijn-voor-fysieke-aanval",level:2},{value:"Google Drive legt bestandslimieten op, waardoor betalende klanten mogelijk worden afgesloten",id:"google-drive-legt-bestandslimieten-op-waardoor-betalende-klanten-mogelijk-worden-afgesloten",level:2},{value:"Gids voor logische klokontwerpen voor betrouwbare gebeurtenissenvolgorde in gedistribueerde systemen",id:"gids-voor-logische-klokontwerpen-voor-betrouwbare-gebeurtenissenvolgorde-in-gedistribueerde-systemen",level:2},{value:"Frankrijks 3034 km lange HexaTrek Trail geopend voor Thru-Hiking",id:"frankrijks-3034-km-lange-hexatrek-trail-geopend-voor-thru-hiking",level:2},{value:"Ontwikkelaar Raph Levien verhuist van Rust naar C++",id:"ontwikkelaar-raph-levien-verhuist-van-rust-naar-c",level:2},{value:"Coursemate: Wereldwijd verbinden van zelfleerders voor collaboratief online leren",id:"coursemate-wereldwijd-verbinden-van-zelfleerders-voor-collaboratief-online-leren",level:2},{value:"Planten zenden geluiden uit wanneer ze gestrest zijn, wat nieuwe deuren opent voor begrip",id:"planten-zenden-geluiden-uit-wanneer-ze-gestrest-zijn-wat-nieuwe-deuren-opent-voor-begrip",level:2},{value:"Simuleren van ondergronds BBS-systeem uit 1987: Chat, spelletjes en e-mail",id:"simuleren-van-ondergronds-bbs-systeem-uit-1987-chat-spelletjes-en-e-mail",level:2},{value:"Google stelt het uitschakelen van Manifest V2 voor Chrome-extensies uit",id:"google-stelt-het-uitschakelen-van-manifest-v2-voor-chrome-extensies-uit",level:2},{value:"Wine 8.5: Verbeterde vkd3d, WinRT Theme, &amp; Bug Fixes",id:"wine-85-verbeterde-vkd3d-winrt-theme--bug-fixes",level:2},{value:"Aanwervingsproces op basis van cv: Uitbuitend en ondoeltreffend",id:"aanwervingsproces-op-basis-van-cv-uitbuitend-en-ondoeltreffend",level:2},{value:"Ex-SpaceX personeel richtte tientallen ruimtevaartstarters op en haalde 3,6 miljard dollar op.",id:"ex-spacex-personeel-richtte-tientallen-ruimtevaartstarters-op-en-haalde-36-miljard-dollar-op",level:2},{value:"Starship van SpaceX gaat naar lanceerbasis, lancering mogelijk op 10 april.",id:"starship-van-spacex-gaat-naar-lanceerbasis-lancering-mogelijk-op-10-april",level:2},{value:"&#39;ccurl.sh&#39; stelt cURL in staat om Chrome cookies op een beknopte manier te gebruiken",id:"ccurlsh-stelt-curl-in-staat-om-chrome-cookies-op-een-beknopte-manier-te-gebruiken",level:2},{value:"MIT&#39;s Cursus over RNN&#39;s &amp; Transformers voor Diep Leren",id:"mits-cursus-over-rnns--transformers-voor-diep-leren",level:2}];function c(e){const n={a:"a",h2:"h2",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.h2,{id:"amazon-echo-apparaten-slaan-wifi-wachtwoorden-op-in-platte-tekst-waardoor-ze-kwetsbaar-zijn-voor-fysieke-aanval",children:"Amazon Echo apparaten slaan WiFi-wachtwoorden op in platte tekst, waardoor ze kwetsbaar zijn voor fysieke aanval."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Alexa, wat is mijn wifi-wachtwoord?"}),"\nAmazon Echo-apparaten slaan wifi-wachtwoorden op in platte tekst, waardoor aanvallers met fysieke toegang relatief eenvoudig netwerkwachtwoorden kunnen achterhalen. Dit vormt een groot veiligheidsrisico voor hotels of bedrijven die de apparaten gebruiken op hun interne of private draadloze netwerken, waardoor aanvallers toegang krijgen tot alle andere apparatuur op het netwerk en mogelijk de wet op de gegevensbescherming schenden. Het hashen van wachtwoorden is een industriestandaard, en voor een bedrijf dat zijn hardware aan miljoenen heeft verkocht, is het volkomen onaanvaardbaar om deze gegevens niet te versleutelen. Het apparaat versleutelt de API-sleutels voor Spotify zeroconf en eSDK API's niet. Fysieke beveiliging is essentieel bij het ontwerpen van embedded hardware, en Amazon moet dit probleem aanpakken om toekomstige beveiligingslekken te voorkomen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399590",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://dragon863.github.io/blog/alexa.html",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"google-drive-legt-bestandslimieten-op-waardoor-betalende-klanten-mogelijk-worden-afgesloten",children:"Google Drive legt bestandslimieten op, waardoor betalende klanten mogelijk worden afgesloten"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Google Drive voert een verrassingsuitrol van bestandslimieten uit, waardoor sommige gebruikers worden afgesloten."}),"\nGoogle Drive heeft zonder waarschuwing een bestandslimiet ingesteld, waardoor betalende klanten die geen nieuwe bestanden kunnen uploaden mogelijk worden afgesloten; Reddit-gebruikers hebben de afgelopen twee maanden al over dit probleem geklaagd. De plotselinge invoering van een bestandslimiet wordt niet vermeld op de Google One- of Google Workspace-planpagina's of in ondersteuningsdocumenten. Het heeft gebruikers er ook van weerhouden gebruik te maken van de opslag die ze hebben gekocht, omdat de limiet hen verhindert de ruimte te gebruiken. De limiet van 5 miljoen bestanden op Google Drive wordt door veel gebruikers noch aanvaardbaar noch redelijk geacht, omdat deze nergens is gedocumenteerd, en de kosten voor het gebruik van het opslagplan van Google Workspace worden als exorbitant beschouwd. Google beweert dat de limiet een beveiliging is om misbruik van het systeem te voorkomen dat de stabiliteit en veiligheid zou kunnen aantasten, maar toch wordt een dergelijke communicatie met de klant als slecht beschouwd.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397071",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://arstechnica.com/gadgets/2023/03/google-drive-does-a-surprise-rollout-of-file-limits-locking-out-some-users/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"gids-voor-logische-klokontwerpen-voor-betrouwbare-gebeurtenissenvolgorde-in-gedistribueerde-systemen",children:"Gids voor logische klokontwerpen voor betrouwbare gebeurtenissenvolgorde in gedistribueerde systemen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Klokken en causaliteit - Ordening van gebeurtenissen in gedistribueerde systemen (2022)."}),"\nLogische klokken zijn essentieel voor het ordenen van gebeurtenissen in gedistribueerde systemen, waarbij Lamport- en vectorklokken populaire ontwerpen zijn. Lamportklokken geven oplopende nummers binnen een knooppunt, terwijl vectorklokken knooppunt-ID's en respectieve gebeurtenis-ID's bijhouden voor gelijktijdige vergelijking van gebeurtenissen. Gestippelde vectorklokken en vectortimestamps optimaliseren tijdstempelcontroles en maken ordening van gebeurtenissen over knooppunten mogelijk. Versievectoren volgen gegevensversies in opslagknooppunten met meerdere leiders. Lamport Causale Klok legt causaliteit vast, maar vereist meer ruimte en tijdscomplexiteit. Total Order vereist sequenti\xeble ordening op basis van temporele en causale relaties. Logische klokken zijn cruciaal in collaboratieve bewerkingstoepassingen. Azure Time Sync gebruikt PTP, terwijl AWS en Google Cloud NTP gebruiken. Het artikel wijst op de beperkingen van het als absoluut beschouwen van tijd en benadrukt het belang van de ordening van gebeurtenissen in banktransacties.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399603",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.exhypothesi.com/clocks-and-causality/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"frankrijks-3034-km-lange-hexatrek-trail-geopend-voor-thru-hiking",children:"Frankrijks 3034 km lange HexaTrek Trail geopend voor Thru-Hiking"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Hexatrek: De lange afstandswandeling in Frankrijk."}),"\nDe 3034 km lange HexaTrek route in Frankrijk is nu open voor thru-hiking, verbindt 14 nationale parken en kruist de Via Transilvanica route van Roemeni\xeb.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397051",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://en.hexatrek.com",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"ontwikkelaar-raph-levien-verhuist-van-rust-naar-c",children:"Ontwikkelaar Raph Levien verhuist van Rust naar C++"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Verhuizing van Rust naar C++."}),"\nOntwikkelaar Raph Levien kondigt de beslissing aan om van Rust naar C++ over te stappen vanwege de beperkingen van het eerste, zoals het gebrek aan keuzes in het buildsysteem en de trage innovatie, ondanks de veiligheidsgaranties. Levien gelooft dat hij veiligheidsproblemen kan vermijden en dat bugs in geheugenveiligheid niet significant schadelijker zijn dan andere bugs, en dat C++ zich snel ontwikkelt om veiliger te worden. Levien benadrukt het belang van de gemeenschap en uit zijn bezorgdheid over discriminatiebeleid en schijnbaar overheersende voorstanders van Rust. Het artikel is echter satirisch, en sommige lezers tonen belangstelling voor C++ boven Rust.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35400047",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://raphlinus.github.io/rust/2023/04/01/rust-to-cpp.html",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"coursemate-wereldwijd-verbinden-van-zelfleerders-voor-collaboratief-online-leren",children:"Coursemate: Wereldwijd verbinden van zelfleerders voor collaboratief online leren"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Coursemate - connect with other self learners."}),"\nCoursemate is een platform voor self learners om in contact te komen en samen te werken aan online cursussen met peers in hun land of over de hele wereld. Het platform kan integreren met de favoriete online cursussen van gebruikers en het duurt minder dan een minuut om het op te zetten. Sommige gebruikers suggereren dat Coursemate zou kunnen profiteren van meer specifieke leerdoelen naast de huidige focus op frontend en backend onderwerpen. Daarnaast zouden gebruikers graag meer community voorbeelden en mentorschap mogelijkheden zien. Sommige gebruikers stellen ook voor om niet alleen te filteren op leeftijd en land, maar ook op interesse. Ondanks enkele punten van kritiek is de website goed uitgevoerd en eenvoudig. Sommige gebruikers wensen een platform om in contact te komen met deskundigen die specifieke cursusinhoud kunnen helpen uitleggen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35398480",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.coursem8.com/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"planten-zenden-geluiden-uit-wanneer-ze-gestrest-zijn-wat-nieuwe-deuren-opent-voor-begrip",children:"Planten zenden geluiden uit wanneer ze gestrest zijn, wat nieuwe deuren opent voor begrip"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"De geluiden die planten onder stress uitzenden zijn luchtgeluiden en informatief."}),"\nPlanten kunnen informatieve luchtgeluiden uitzenden wanneer zij onder stress staan, wat nieuwe wegen opent om hun interacties met de omgeving te begrijpen. Dit nieuwe gebied van de bio-akoestiek van planten introduceert het potentieel voor akoestische communicatie van planten, die kan worden gedetecteerd door modellen voor machinaal leren en die de landbouw verder kan be\xefnvloeden dan de traditionele signalen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35396156",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.cell.com/cell/fulltext/S0092-8674(23)00262-3",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"simuleren-van-ondergronds-bbs-systeem-uit-1987-chat-spelletjes-en-e-mail",children:"Simuleren van ondergronds BBS-systeem uit 1987: Chat, spelletjes en e-mail"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"ChatGPT simuleert BBS-systeem van 1987."}),"\nHet artikel gaat over het simuleren van een BBS-systeem uit 1987, inclusief chat, spelletjes en e-mail. Gebruikers kunnen een account aanmaken, nieuws en documentatie lezen, tekstbestanden bekijken en communiceren met andere gebruikers. Castle Quest, een op tekst gebaseerd spel, kan op het systeem worden gespeeld. Met ShareGPT kunnen codefragmenten in gesprekken worden gedeeld. De historische nauwkeurigheid van ChatGPT's uitvoer is twijfelachtig maar interessant. Een gebruiker stelt voor een BBS uit 1987 te simuleren met extra functies. Het artikel geeft een nostalgische kijk op de technologie van toen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35396165",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://sharegpt.com/c/ICZsSl7",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"google-stelt-het-uitschakelen-van-manifest-v2-voor-chrome-extensies-uit",children:"Google stelt het uitschakelen van Manifest V2 voor Chrome-extensies uit"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Uitstel wijzigingen Manifest V2 uitfasering."}),"\nGoogle heeft alle experimenten in januari om Manifest V2 uit te schakelen in pre-release kanalen van Chrome en wijzigingen aan de featured badge in de Chrome Webstore uitgesteld, en het zal alle downstream mijlpalen evalueren. Ontwikkelaars krijgen voldoende tijd om hun extensies bij te werken en te testen na de lancering van deze nieuwe mogelijkheden voordat Manifest V2 wordt uitgeschakeld. Google's toezegging om Manifest V3 uit te rollen zal naar verwachting de beveiliging, privacy en prestaties voor hun gebruikers verbeteren. Er was feedback van de ontwikkelaarsgemeenschap over de moeilijkheden bij het gebruik van Manifest V3, waarvan een deel is aangepakt, maar er zijn nog steeds verbeteringen nodig en Google blijft zich inzetten voor de overgang.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35402698",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://groups.google.com/a/chromium.org/g/chromium-extensions/c/zQ77HkGmK9E/m/HjaaCIG-BQAJ",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"wine-85-verbeterde-vkd3d-winrt-theme--bug-fixes",children:"Wine 8.5: Verbeterde vkd3d, WinRT Theme, & Bug Fixes"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Wijn 8.5."}),"\nWine release 8.5 komt met verbeterde vkd3d, WinRT Theme, en bug fixes, inclusief betere foutrapportage in IDL compiler, ondersteuning voor UIA_IsOffscreenPropertyId aan MSAA providers, en het volledig initialiseren van i386 FPU context op ARM64. Binaire pakketten beschikbaar voor verschillende distributies, en broncode direct beschikbaar vanaf git repository. Bug fixes omvatten mscoree, imm32, en LDAP bind.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35398643",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.winehq.org/announce/8.5",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"aanwervingsproces-op-basis-van-cv-uitbuitend-en-ondoeltreffend",children:"Aanwervingsproces op basis van cv: Uitbuitend en ondoeltreffend"}),"\n",(0,t.jsxs)(n.p,{children:["**Wie een cv opstuurt, heeft al verloren.\nHet traditionele aanwervingsproces op basis van cv is uitbuitend en uiteindelijk ineffectief, omdat werkgevers het vooral gebruiken om tijd en kosten te besparen ten koste van de sollicitant. CV's kunnen worden genegeerd, en persoonlijke aanbevelingen en netwerken zijn effectievere methoden om een baan te krijgen, en omzeilen het gebrekkige en oneerlijke proces. Academische aanwerving is ongelooflijk demotiverend en nepotisme kan ethische problemen opleveren. Werkzoekenden moeten doen wat ze kunnen om het systeem te omzeilen, maar cv's serieus nemen blijft noodzakelijk. Het bericht biedt hulpmiddelen voor werkzoekenden om zich te onderscheiden, waaronder het schrijven van een sollicitatiebrief of het gebruik van een AI-tool om deze in twee minuten te schrijven.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397271",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.residentcontrarian.com/p/he-who-submits-a-resume-has-already",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"ex-spacex-personeel-richtte-tientallen-ruimtevaartstarters-op-en-haalde-36-miljard-dollar-op",children:"Ex-SpaceX personeel richtte tientallen ruimtevaartstarters op en haalde 3,6 miljard dollar op."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Alumni van SpaceX breiden uit en geven vorm aan de startup-economie."}),"\nEx-werknemers van SpaceX hebben tientallen ruimtevaartondernemingen opgericht en daarmee 3,6 miljard dollar opgehaald om de innovatie op het gebied van navigatie in een lage baan om de aarde en de levering van nuttige ladingen te stimuleren. Medeoprichters profiteren van de gemeenschap en de risicovolle tolerantie die bij SpaceX is ontstaan, waarbij de lanceerdiensten ook technologische prototypes, machines en het verzenden van navigatiesatellieten helpen. Software-as-a-service industrie groeit, ten dienste van het ruimtevaart startup ecosysteem. Het tempo van NASA en Boeing zou kunnen profiteren van het stimuleren van een startup-cultuur, aangezien verouderde code en rommel gevestigde bedrijven tegenhouden. Kansen in de ruimteverkenning zorgen voor liquiditeit in de markt, en investeerders krijgen miljoenen voor riskante moonshots. Sommige commentaren suggereren dat het artikel aanvoelt als een persbericht.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35404823",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://interactive.satellitetoday.com/via/april-2023/how-spacex-alums-are-branching-out-and-shaping-the-startup-economy/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"starship-van-spacex-gaat-naar-lanceerbasis-lancering-mogelijk-op-10-april",children:"Starship van SpaceX gaat naar lanceerbasis, lancering mogelijk op 10 april."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"SpaceX verplaatst Starship naar lanceerplaats, en liftoff zou slechts enkele dagen verwijderd kunnen zijn."}),"\nSpaceX heeft zijn Starship verplaatst naar een lanceerbasis in Zuid-Texas, die mogelijk al op 10 april kan worden gelanceerd, afhankelijk van de FAA-vergunning. De gigantische Super Heavy raket is bedoeld om NASA te dienen als maanlander voor de Artemis maanmissies. SpaceX heeft meer dan 1 miljard dollar ge\xefnvesteerd in zijn lanceertoren om zijn Starship en Super Heavy te ondersteunen, die het voorzichtiger heeft ontwikkeld in zijn faciliteit in Zuid-Texas. Indien succesvol, zou dit de lage aardbaan gemakkelijker beschikbaar kunnen maken voor professionals.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35405030",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://arstechnica.com/science/2023/04/spacex-moves-starship-to-launch-site-and-liftoff-could-be-just-days-away/",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"ccurlsh-stelt-curl-in-staat-om-chrome-cookies-op-een-beknopte-manier-te-gebruiken",children:"'ccurl.sh' stelt cURL in staat om Chrome cookies op een beknopte manier te gebruiken"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Cookies van Chrome (CDP) gebruiken in cURL zonder te kopi\xebren."}),'\n\'ccurl.sh\' is een bash script dat cURL in staat stelt om Chrome cookies te gebruiken zonder de noodzaak van een GUI tool zoals Postman, door gebruik te maken van het Chrome DevTools protocol om cookies van een specifiek tabblad van de lokale Chrome instantie te dumpen in de header van een cURL commando, en het vermijden van cookie lekkage in de shell geschiedenis bestand; het script vereist bash, websocat en jq om te draaien, en een tabblad met de te gebruiken cookies te openen in Chrome, dat gestart moet worden met "google-chrome-stable --remote-debugging-port=9222", en kan ge\xefnstalleerd worden door het script te kopi\xebren naar "/usr/bin/ccurl" en het uitvoerbaar te maken.\n',(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399218",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://github.com/fipso/ccurl.sh",children:"Artikel"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"mits-cursus-over-rnns--transformers-voor-diep-leren",children:"MIT's Cursus over RNN's & Transformers voor Diep Leren"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"MIT 6.S191: Recurrente neurale netwerken, transformatoren en aandacht."}),"\nMIT's 6.S191 cursus behandelt terugkerende neurale netwerken (RNN's), transformatoren en aandacht voor diep leren, zoals te zien is op YouTube. Reacties op de video vari\xebren van vragen over de naamgevingsconventies voor parameters tot vragen om aanbevelingen over waar je neurale netwerken en basiskennis van deep learning kunt leren. Het gebruik van TensorFlow in de cursus en het uploaden van de video's naar YouTube-kanalen van individuele medewerkers worden ook besproken.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35405338",children:"Discussion Service"}),", ",(0,t.jsx)(n.a,{href:"https://www.youtube.com/watch?v=ySEx_Bqxvvo",children:"Artikel"}),"."]})]})}function h(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}}}]);